const webhook = $input.first()?.json || {};
const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : {};
const headers = Object.fromEntries(Object.entries(webhook.headers || {}).map(([key, value]) => [String(key).toLowerCase(), value]));
const expectedKey = String($env.VOICEFLOW_WEBHOOK_KEY || '').trim();
const presentedKey = String(headers['x-javedai-key'] || '').trim();
const DRY_RUN = true;

function safeEqual(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return mismatch === 0;
}

function cleanText(value, maxLength = 300) {
  return String(value || '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, maxLength);
}

function cleanEmail(value) {
  return cleanText(value, 254).toLowerCase();
}

function cleanPhone(value) {
  const raw = cleanText(value, 40);
  if (!raw) return '';
  const hasPlus = raw.startsWith('+');
  const digits = raw.replace(/\D/g, '').slice(0, 15);
  return digits ? (hasPlus ? '+' : '') + digits : '';
}

const fullName = cleanText(body.name || [body.first_name, body.last_name].filter(Boolean).join(' '), 120);
const nameParts = fullName.split(' ').filter(Boolean);
const firstName = cleanText(body.first_name || nameParts[0] || '', 60);
const lastName = cleanText(body.last_name || nameParts.slice(1).join(' '), 60);
const email = cleanEmail(body.email);
const phone = cleanPhone(body.phone);
const consent = body.consent_to_contact === true || String(body.consent_to_contact || '').toLowerCase() === 'true';
const errors = [];

if (!expectedKey) errors.push('server_auth_not_configured');
if (!safeEqual(presentedKey, expectedKey)) errors.push('unauthorized');
if (!email && !phone) errors.push('email_or_phone_required');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('invalid_email');
if (phone && phone.replace(/\D/g, '').length < 7) errors.push('invalid_phone');
if (!consent) errors.push('consent_to_contact_required');

const useCase = cleanText(body.use_case || body.message || body.intent, 1000);
const budget = cleanText(body.budget, 80);
const timeline = cleanText(body.timeline, 80);
let leadScore = 20;
if (email) leadScore += 10;
if (phone) leadScore += 15;
if (cleanText(body.company, 150)) leadScore += 10;
if (useCase.length >= 40) leadScore += 15;
if (budget) leadScore += 15;
if (timeline) leadScore += 15;
leadScore = Math.min(100, leadScore);

const qualification = leadScore >= 70 ? 'high' : leadScore >= 50 ? 'medium' : 'low';
const route = qualification === 'high' ? 'priority_sales_callback' : qualification === 'medium' ? 'sales_nurture' : 'self_service_nurture';
const seed = [email, phone, String(body.event_id || ''), useCase].join('|').toLowerCase();
let hash = 2166136261;
for (let index = 0; index < seed.length; index += 1) {
  hash ^= seed.charCodeAt(index);
  hash = Math.imul(hash, 16777619);
}
const generatedId = 'vf-' + (hash >>> 0).toString(16);

return [{ json: { auth_valid: safeEqual(presentedKey, expectedKey), valid: errors.length === 0, errors, dry_run: DRY_RUN, request_id: cleanText(body.event_id, 120) || generatedId, received_at: new Date().toISOString(), lead_score: leadScore, qualification, route, lead: { first_name: firstName, last_name: lastName, full_name: [firstName, lastName].filter(Boolean).join(' '), email, phone, company: cleanText(body.company, 150), website: cleanText(body.website, 300), use_case: useCase, budget, timeline, source: cleanText(body.source || 'voiceflow', 80), consent_to_contact: consent } } }];

const data = $input.first().json;
const unauthorized = !data.auth_valid;
return [{ json: { response_code: unauthorized ? 401 : 400, response: { ok: false, status: unauthorized ? 'unauthorized' : 'invalid_request', request_id: data.request_id || null, errors: data.errors || ['invalid_request'] } } }];

const data = $input.first().json;
const store = $getWorkflowStaticData('global');
store.seen_requests = store.seen_requests || {};
const now = Date.now();
const ttlMs = 24 * 60 * 60 * 1000;
for (const [key, timestamp] of Object.entries(store.seen_requests)) {
  if (!Number.isFinite(timestamp) || now - timestamp > ttlMs) delete store.seen_requests[key];
}
const duplicate = Boolean(store.seen_requests[data.request_id]);
if (!duplicate) store.seen_requests[data.request_id] = now;
return [{ json: { ...data, duplicate, idempotency_window_hours: 24 } }];

const search = $input.first().json || {};
const source = $node['Check Idempotency'].json;
const lead = source.lead;
const existing = Array.isArray(search.results) && search.results.length > 0 ? search.results[0] : null;
const properties = {};
if (lead.email) properties.email = lead.email;
if (lead.first_name) properties.firstname = lead.first_name;
if (lead.last_name) properties.lastname = lead.last_name;
if (lead.phone) properties.phone = lead.phone;
if (lead.company) properties.company = lead.company;
if (lead.website) properties.website = lead.website;
if (!existing) properties.lifecyclestage = 'lead';
return [{ json: { ...source, hubspot_contact_id: existing?.id || '', hubspot_action: existing ? 'update' : 'create', crm_properties: properties } }];

const hubspot = $input.first().json || {};
const source = $node['Prepare HubSpot Upsert'].json;
return [{ json: { response_code: 200, response: { ok: true, status: 'accepted', dry_run: false, request_id: source.request_id, lead_score: source.lead_score, qualification: source.qualification, route: source.route, next_action: source.route === 'priority_sales_callback' ? 'offer_immediate_callback_or_booking' : 'continue_voiceflow_nurture', hubspot_action: source.hubspot_action, hubspot_contact_id: hubspot.id || source.hubspot_contact_id || null } } }];
